 // Mutator: \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u0441\u044F \u043A\u0430\u043A 'alice'\necho $user->name;           // Accessor: \u0432\u044B\u0432\u0435\u0434\u0435\u0442 'Alice'\necho $user->full_name;      // 'Alice Smith'\n"})}),"\n",(0,r.jsxs)(n.h3,{id:"casts--\u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u043E\u0435-\u043F\u0440\u0438\u0432\u0435\u0434\u0435\u043D\u0438\u0435-\u0442\u0438\u043F\u043E\u0432",children:[(0,r.jsx)(n.code,{children:"$casts"})," \u2014 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u043E\u0435 \u043F\u0440\u0438\u0432\u0435\u0434\u0435\u043D\u0438\u0435 \u0442\u0438\u043F\u043E\u0432"]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-php",children:"class Order extends Model\n{\n    protected $casts = [\n        'paid_at'    => 'datetime',          // Carbon instance\n        'metadata'   => 'array',             // JSON \u2192 array \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\n        'total'      => 'decimal:2',\n        'is_shipped' => 'boolean',\n        'status'     => OrderStatus::class,  // Enum (PHP 8.1+)\n    ];\n}\n\n$order = Order::find(1);\necho $order->paid_at->format('d.m.Y'); // Carbon\n$order->metadata['key'] = 'value';     // \u0420\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u043A\u0430\u043A \u043C\u0430\u0441\u0441\u0438\u0432, \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F \u043A\u0430\u043A JSON\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"6-model-events-\u0438-observers",children:"6. Model Events \u0438 Observers"}),"\n",(0,r.jsx)(n.p,{children:"Eloquent \u0433\u0435\u043D\u0435\u0440\u0438\u0440\u0443\u0435\u0442 \u0441\u043E\u0431\u044B\u0442\u0438\u044F \u0432 \u043A\u043B\u044E\u0447\u0435\u0432\u044B\u0445 \u0442\u043E\u0447\u043A\u0430\u0445 \u0436\u0438\u0437\u043D\u0435\u043D\u043D\u043E\u0433\u043E \u0446\u0438\u043A\u043B\u0430 \u043C\u043E\u0434\u043